/* Shared festival campaign: derived from real route and investigation records.
   No new score, parallel save file, or fabricated research result. */
window.TryvoCampaign=(()=>{
 'use strict';
 const D=window.TryvoData,RE=window.TryvoRescueEngine;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const chapters=[
  {id:'first-light',type:'route',title:'Bring the lantern makers',skill:'Planning',place:'Tram depot',x:12,y:39,why:'The first arrivals can light the square. Connect a route around the closure.',handoff:'The lantern makers have arrived. Mira still needs to understand why so many guests missed the previous festival.'},
  {id:'attendance',type:'mission',title:'The empty seats',skill:'Evidence',place:'Festival office',x:31,y:35,why:'Before rebuilding this year’s invitation plan, investigate the price and transport changes at the previous event.',handoff:'Your investigation proposal goes into Mira’s planning file. Now choose how the courtyard should serve the arriving guests.'},
  {id:'courtyard',type:'mission',title:'One courtyard, three plans',skill:'Trade-offs',place:'The courtyard',x:45,y:46,why:'Guests need a place to gather. Balance immediate shade, water, budget and future upkeep.',handoff:'Your courtyard recommendation is recorded. The musicians and food vendors are ready for their pickup.'},
  {id:'all-aboard',type:'route',title:'Bring the town together',skill:'Planning',place:'Town stops',x:29,y:63,why:'With the gathering plan recorded, connect the musicians and food vendors to the festival.',handoff:'The musicians and vendors have arrived. The festival exhibition still needs its restored photograph delivered to the right keeper.'},
  {id:'archive',type:'mission',title:'The archive handoff',skill:'Deduction',place:'Festival exhibition',x:48,y:70,why:'The archive is lending a photograph to the exhibition. Work out who is responsible for it.',handoff:'Your delivery recommendation joins the festival file. Next, help the vendors interpret their display trial before choosing a plan.'},
  {id:'market',type:'mission',title:'The bigger stall',skill:'Quantities',place:'Night market',x:65,y:61,why:'The vendors’ earlier trial has competing claims. Compare rates and propose a fairer display test.',handoff:'Your market recommendation is recorded. One decision remains before the final arrivals: where should the performance happen?'},
  {id:'forecast',type:'mission',title:'A roof for the evening',skill:'Uncertainty',place:'Performance square',x:80,y:37,why:'Choose the performance venue before the weather is known. Your recorded choice becomes the final tram’s destination.',handoff:'Your venue choice now names the final destination. Open the river crossing and bring the remaining crew to that venue.'},
  {id:'across-the-river',type:'route',title:'The final arrivals',skill:'Planning',place:'River crossing',x:87,y:58,why:'Send the bridge signal, collect both groups and deliver the final crew to the venue you selected.',handoff:'The route is complete. Review the festival you helped organise: the arrivals, the decisions and the questions still worth revisiting.'}
 ];
 const chapter=id=>chapters.find(c=>c.id===id);
 function record(s,id){const c=chapter(id);if(!c)return null;return c.type==='route'?(RE.valid(s.rescue)?s.rescue.history:[]).filter(r=>r.level===id&&r.success).at(-1)||null:s.history.filter(r=>r.taskId===id&&r.contentVersion===2).at(-1)||null;}
 const done=(s,id)=>{const r=record(s,id);return !!r&&(id!=='across-the-river'||!r.destination||r.destination===destination(s));};
 const count=s=>chapters.filter(c=>done(s,c.id)).length;
 const next=s=>chapters.find(c=>!done(s,c.id))||null;
 const available=(s,id)=>{const i=chapters.findIndex(c=>c.id===id);return i>=0&&(done(s,id)||chapters.slice(0,i).every(c=>done(s,c.id)));};
 function destination(s){const r=record(s,'forecast');return !r?'Festival':r.answer==='inside'||r.answer==='certain'?'Indoor hall':'Outdoor stage';}
 function effect(s,id){const r=record(s,id),c=chapter(id);if(!r)return 'Waiting for your contribution.';if(c.type==='route')return `${id==='across-the-river'?'Final crew at '+(r.destination||'festival (earlier route record)').toLowerCase():'Riders delivered'} · ${r.cost} repair tokens.`;const m=D.missions.find(m=>m.id===id),choice=m.options.find(o=>o.id===r.answer)?.label||'Decision recorded';return choice;}
 function status(s,c){const r=record(s,c.id);return !r?'Not yet recorded':c.id==='across-the-river'&&!done(s,c.id)?'Venue changed · run the final delivery again':c.type==='route'?'Arrivals complete':r.score===100?'Decision supported':'Decision recorded · review feedback';}
 function routeLevel(s,l){if(l.id!=='across-the-river')return l;return {...l,destination:destination(s),brief:`${l.brief} Your performance destination: ${destination(s).toLowerCase()}.`,reply:`The final crew reached the ${destination(s).toLowerCase()} you planned for. The festival file now holds the decisions behind tonight.`};}
 const icons={Evidence:'⌕','Trade-offs':'⚖',Deduction:'◇',Quantities:'▥',Uncertainty:'⚄',Planning:'⌁'};
 function launch(s,c,label){return `<button class="button campaign-launch" data-campaign="play" data-chapter="${c.id}" ${available(s,c.id)?'':'disabled'}>${label|| (done(s,c.id)?'Revisit chapter':'Enter chapter')} <span aria-hidden="true">→</span></button>`;}
 function primary(s){const active=s.active&&s.active.phase!=='result'&&chapter(s.active.taskId);if(active)return `<button class="button" data-action="resume">Resume ${esc(active.title)} →</button>`;const n=next(s);return n?launch(s,n,count(s)?'Continue the festival':'Begin the festival'): '<button class="button" data-campaign="finale">See your festival →</button>';}
 function summary(s){return `<section class="festival-summary"><div><span class="small-label">Your Lantern Festival</span><h2>${count(s)} of 8 chapters contributed</h2><p>Route arrivals and decisions share one festival record. Completion records participation, not mastery.</p></div><progress max="8" value="${count(s)}" aria-label="Festival chapters contributed">${count(s)} of 8</progress>${primary(s)}<a href="#festival-file">Open the festival file</a></section>`;}
 function ledger(s,expanded=false){return `<details class="festival-file" id="festival-file" ${expanded?'open':''}><summary>The festival you’re shaping <span>${count(s)} / 8 contributions</span></summary><p>Your latest completed attempts are carried forward. Revisiting a decision updates this plan; earlier records stay in your journal. A recorded recommendation can still need revision.</p><div class="festival-ledger">${chapters.map(c=>`<article class="${done(s,c.id)?'recorded':''}"><span class="ledger-icon">${icons[c.skill]}</span><div><h3>${esc(c.place)}</h3><p>${esc(effect(s,c.id))}</p><small>${status(s,c)}</small></div>${done(s,c.id)?`<button class="text-button" data-campaign="inspect" data-chapter="${c.id}">Review<span class="sr-only"> ${esc(c.title)}</span></button>`:''}</article>`).join('')}</div></details>`;}
 function home(s){const n=next(s),finished=!n;return `<section class="campaign-home"><div class="campaign-heading"><div><span class="small-label">Try. Learn. Own it.</span><h1>One town. One festival.<br>A world of decisions.</h1><p>Bring the Lantern Festival to life with Mira. Connect the streets, question the evidence and shape what happens next.</p></div><div class="campaign-count"><strong>${count(s)}<span> / 8</span></strong><span>chapters contributed</span><progress max="8" value="${count(s)}" aria-label="Festival campaign progress"></progress></div></div><div class="campaign-world"><div class="campaign-map" role="group" aria-label="Lantern Festival campaign map"><img src="assets/festival-town.png" alt="The shared festival town: depot, office, courtyard, exhibition, market and performance square" width="1536" height="1024"><svg viewBox="0 0 1000 667" preserveAspectRatio="none" aria-hidden="true"><polyline points="${chapters.map(c=>`${c.x*10},${c.y*6.67}`).join(' ')}"/></svg>${chapters.map((c,i)=>`<button class="campaign-pin ${done(s,c.id)?'complete':available(s,c.id)?'current':'later'}" style="left:${c.x}%;top:${c.y}%" data-campaign="inspect" data-chapter="${c.id}" aria-label="Chapter ${i+1}: ${esc(c.title)}, ${done(s,c.id)?'contributed':available(s,c.id)?'ready':'later chapter'}"><b>${done(s,c.id)?'✓':i+1}</b><span>${esc(c.place)}</span></button>`).join('')}<div class="campaign-map-caption">One shared world · eight connected chapters</div></div><aside class="campaign-dispatch"><div class="dispatch-character"><span class="mira-avatar">${window.TryvoArt.portrait()}</span><div><strong>Mira’s festival notebook</strong><span>Your decisions bring us together.</span></div></div><span class="small-label">${finished?'The night you helped shape':'Next in your story'}</span><h2>${esc(n?.title||'Your festival is ready to review.')}</h2><p>${esc(n?.why||'Every arrival has a route. Every recommendation has a reason. Revisit the choices and see what you contributed.')}</p>${primary(s)}<p class="caption">No timer. Pause and return whenever you like.</p><div class="dispatch-foot"><strong>${count(s)?'Carried forward':'Your shared objective'}</strong><p>${count(s)?esc(effect(s,[...chapters].reverse().find(c=>done(s,c.id)).id)):'Bring the people, places and plans together for one festival.'}</p></div></aside></div><section class="skill-districts"><h2>Five ways to think. One world to shape.</h2><div class="skill-tiles">${[['attendance','Weigh evidence and explain conclusions.'],['courtyard','Balance competing objectives.'],['archive','Find what must be true.'],['market','Compare quantities and use resources.'],['forecast','Plan under incomplete information.']].map(([id,desc])=>{const c=chapter(id);return `<button data-campaign="inspect" data-chapter="${id}" class="skill-tile"><span aria-hidden="true">${icons[c.skill]}</span><strong>${c.skill}</strong><p>${desc}</p><small>${status(s,c)}</small></button>`;}).join('')}</div></section><section class="campaign-path"><div class="section-top"><div><h2>The story so far—and what comes next.</h2><p>Routes connect the town. Your investigations shape its plans.</p></div><a href="#festival-file">View your shared festival file</a></div><ol>${chapters.map((c,i)=>`<li id="chapter-${c.id}" class="campaign-chapter ${done(s,c.id)?'complete':''}"><span class="chapter-number">${done(s,c.id)?'✓':i+1}</span><div><small>${c.skill} · ${c.place}</small><h3>${esc(c.title)}</h3><p>${esc(done(s,c.id)?effect(s,c.id):c.why)}</p></div>${available(s,c.id)?launch(s,c):`<button class="text-button" data-campaign="inspect" data-chapter="${c.id}">Preview chapter</button>`}</li>`).join('')}</ol></section>${ledger(s)}</section>`;}
 function context(s,id){const c=chapter(id);if(!c)return '';const i=chapters.indexOf(c),prior=chapters.slice(0,i).reverse().find(x=>done(s,x.id));return `<aside class="campaign-context"><a href="#explore">← Lantern Festival</a><span>Chapter ${i+1} of 8 · ${c.skill}</span><strong>${esc(c.why)}</strong>${prior?`<p>From your festival file: ${esc(effect(s,prior.id))}</p>`:''}</aside>`;}
 function handoff(s,id){const c=chapter(id);if(!c)return '';const n=next(s);return `<section class="campaign-handoff"><span class="small-label">Added to your festival file</span><h3>${esc(effect(s,id))}</h3><p>${esc(c.handoff)}</p><div>${n?launch(s,n,'Continue: '+n.title):'<button class="button" data-campaign="finale">See your completed festival</button>'}<a href="#explore">Return to the town</a></div></section>`;}
 function finale(s){return `<div class="festival-finale"><img src="assets/festival-town.png" alt="The lantern festival town" width="1536" height="1024"><h3>${count(s)===8?'You helped bring the festival together.':'Your festival is taking shape.'}</h3><p>${count(s)} of 8 contributions recorded. Performance destination: <strong>${destination(s)}</strong>. Your plans remain inspectable, including recommendations worth revisiting.</p>${ledger(s,true)}<div class="independent-epilogue"><h3>A new situation. Your own judgment.</h3><p>Try a separate library investigation without hints. It stays outside festival completion and is not proof of general improvement.</p><button class="button secondary" data-action="start" data-id="library-check">${s.seen['library-check']?'Revisit the independent check':'Try the independent check'}</button></div></div>`;}
 return {chapters,chapter,record,done,count,next,available,destination,effect,status,routeLevel,launch,primary,summary,ledger,home,context,handoff,finale};
})();
